module BrokenClockFix(\n    input clk,\n    input rst_n,\n    input start,\n    input format,\n    input [15:0] time_in,\n    output reg [15:0] time_out,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] INIT            = 3'd1;\n    localparam [2:0] CORRECT_MINUTES = 3'd2;\n    localparam [2:0] CORRECT_HOURS   = 3'd3;\n    localparam [2:0] DONE_STATE      = 3'd4;\n\n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [4:0] h_count;\n    reg [5:0] m_count;\n    reg [7:0] cycle_counter;\n\n    reg [3:0] orig_H1, orig_H2, orig_M1, orig_M2;\n    reg [3:0] best_H1, best_H2, best_M1, best_M2;\n    reg [2:0] best_M_changes, best_H_changes;\n    reg [5:0] best_minute_val;\n    reg [4:0] best_hour_val;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state             <= IDLE;\n            done              <= 1'b0;\n            time_out          <= 16'd0;\n            cycle_counter     <= 8'd0;\n            m_count           <= 6'd0;\n            h_count           <= 5'd0;\n            orig_H1           <= 4'd0;\n            orig_H2           <= 4'd0;\n            orig_M1           <= 4'd0;\n            orig_M2           <= 4'd0;\n            best_M_changes    <= 3'd2;\n            best_H_changes    <= 3'd2;\n            best_minute_val   <= 6'd59;\n            best_hour_val     <= 5'd23;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            if (cycle_counter >= 8'd100) begin\n                state <= DONE_STATE;\n            end\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        cycle_counter <= 8'd0;\n                        state <= INIT;\n                    end\n                end\n\n                INIT: begin\n                    orig_H1        <= time_in[15:12];\n                    orig_H2        <= time_in[11:8];\n                    orig_M1        <= time_in[7:4];\n                    orig_M2        <= time_in[3:0];\n                    best_M_changes <= 3'd2;\n                    best_minute_val <= 6'd59;\n                    m_count        <= 6'd0;\n                    state          <= CORRECT_MINUTES;\n                end\n\n                CORRECT_MINUTES: begin\n                    if (m_count <= 6'd59) begin\n                        // Compute current digit combo\n                        reg [3:0] M1_candidate = m_count / 6'd10;\n                        reg [3:0] M2_candidate = m_count % 6'd10;\n                        reg [1:0] changes = (M1_candidate != orig_M1) + (M2_candidate != orig_M2);\n\n                        if ((changes < best_M_changes) ||\n                            ((changes == best_M_changes) && (m_count < best_minute_val))) begin\n                            best_M_changes  <= changes;\n                            best_minute_val <= m_count;\n                            best_M1         <= M1_candidate;\n                            best_M2         <= M2_candidate;\n                        end\n                        m_count <= m_count + 6'd1;\n                    end else begin\n                        // Initialize hour correction\n                        best_H_changes <= 3'd2;\n                        best_hour_val  <= format ? 5'd12 : 5'd23;\n                        h_count        <= format ? 5'd1 : 5'd0;\n                        state <= CORRECT_HOURS;\n                    end\n                end\n\n                CORRECT_HOURS: begin\n                    if ((!format && (h_count >= 5'd24)) || (format && (h_count >= 5'd13))) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        // Compute current hour digits\n                        reg [3:0] H1_cand;\n                        reg [3:0] H2_cand;\n                        if (format) begin\n                            H1_cand = (h_count <= 5'd9) ? 4'd0 : 4'd1;\n                            H2_cand = (h_count <= 5'd9) ? h_count[3:0] : (h_count - 5'd10);\n                        end else begin\n                            H1_cand = h_count / 5'd10;\n                            H2_cand = h_count % 5'd10;\n                        end\n\n                        reg [1:0] changes = (H1_cand != orig_H1) + (H2_cand != orig_H2);\n\n                        if ((changes < best_H_changes) ||\n                            ((changes == best_H_changes) && (h_count < best_hour_val))) begin\n                            best_H_changes <= changes;\n                            best_hour_val  <= h_count;\n                            best_H1        <= H1_cand;\n                            best_H2        <= H2_cand;\n                        end\n                        h_count <= h_count + 5'd1;\n                    end\n                end\n\n                DONE_STATE: begin\n                    time_out <= {best_H1, best_H2, best_M1, best_M2};\n                    done     <= 1'b1;\n                    state    <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule